document.addEventListener('DOMContentLoaded', () => {
    // Cart functionality
    const cartBtn = document.getElementById('cart-btn');
    const cartCountEl = document.getElementById('cart-count');
    const addToCartBtns = document.querySelectorAll('.add-to-cart-btn');
    const liveRegion = document.getElementById('a11y-live-region');

    let cartCount = 0;

    /**
     * Updates the cart count and announces to screen readers
     * @param {string} productName 
     */
    function addToCart(productName) {
        cartCount++;

        // Update visual badge
        cartCountEl.textContent = cartCount;

        // Update aria-label on the cart button for screen readers
        const itemText = cartCount === 1 ? 'item' : 'items';
        cartBtn.setAttribute('aria-label', `Shopping Cart, ${cartCount} ${itemText}`);

        // Announce action politely via live region
        liveRegion.textContent = `${productName} added to cart. You now have ${cartCount} ${itemText} in your cart.`;

        // Temporary feedback on the button
        const btn = document.querySelector(`button[data-product="${productName}"]`);
        if (btn) {
            const originalText = btn.innerHTML;
            btn.innerHTML = `Added! <span class="sr-only">to cart</span>`;
            btn.style.backgroundColor = 'var(--color-accent)';
            btn.style.color = 'var(--color-bg)';

            setTimeout(() => {
                btn.innerHTML = originalText;
                btn.style.backgroundColor = '';
                btn.style.color = '';
            }, 2000);
        }
    }

    // Attach event listeners to all Add to Cart buttons
    addToCartBtns.forEach(button => {
        button.addEventListener('click', (e) => {
            const productName = e.currentTarget.getAttribute('data-product');
            if (productName) {
                addToCart(productName);
            }
        });
    });

    // Smooth scroll for anchor links with focus management
    const skipLink = document.querySelector('.skip-link');
    const mainContent = document.getElementById('main-content');

    skipLink.addEventListener('click', (e) => {
        // Ensuring focus is shifted to the main content area when skip link is used
        if (mainContent) {
            mainContent.focus();
        }
    });

    // Clear live region occasionally to prevent clutter if many things are added
    setInterval(() => {
        if (liveRegion.textContent !== '') {
            liveRegion.textContent = '';
        }
    }, 10000);
});

