    margin-bottom: 0;
}

.highlight {
    color: var(--color-accent);
    font-weight: bold;
}

/* Editorial */
.editorial-card {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-md);
    background-color: var(--color-surface);
